import 'package:channel_talk_flutter/channel_talk_flutter.dart';

void main() async {
  await ChannelTalk.boot(
    pluginKey: 'pluginKey',
    memberId: 'memberId',
    memberHash: 'memberHash',
    email: 'email',
    name: 'name',
    mobileNumber: 'mobileNumber',
    avatarUrl: 'avatarUrl',
    hidePopup: false,
    appearance: Appearance.dark,
  );
  ChannelTalk.setListener((event, args) {
    // handle events
  });
  runApp(const App());
}

class App extends StatelessWidget {
  const App({super.key});
  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: () => ChannelTalk.showMessenger(),
      child: const Text('Open Channel Talk'),
    );
  }
}
